require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';if(!isset($_SESSION['id_admin']))redirect('admin_login.php');$id=filter_input(INPUT_POST,'id_pesanan',FILTER_VALIDATE_INT);$action=$_POST['aksi']??'';$q=$pdo->prepare('SELECT * FROM pesanan WHERE id_pesanan=:id');$q->execute(['id'=>$id]);$o=$q->fetch();if($o){if($action==='terima'){$next=['menunggu_verifikasi'=>'diproses','diproses'=>'dikirim','dikirim'=>'selesai'];$status=$next[$o['status']]??$o['status'];$pdo->prepare('UPDATE pesanan SET status=:status WHERE id_pesanan=:id')->execute(['status'=>$status,'id'=>$id]);$pdo->prepare("UPDATE pembayaran SET status_tf='diterima' WHERE id_pesanan=:id")->execute(['id'=>$id]);}elseif($action==='tolak'){$pdo->prepare("UPDATE pesanan SET status='dibatalkan' WHERE id_pesanan=:id")->execute(['id'=>$id]);$pdo->prepare("UPDATE pembayaran SET status_tf='ditolak' WHERE id_pesanan=:id")->execute(['id'=>$id]);}}redirect('dashboard.php?menu=transaksi');